import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"54、【歸妹】 兌下震上","description":"子夏易傳 - 54、【歸妹】 兌下震上","frontmatter":{"title":"54、【歸妹】 兌下震上","description":"子夏易傳 - 54、【歸妹】 兌下震上"},"headers":[],"relativePath":"classics/zixia/056.md","filePath":"classics/zixia/056.md"}'),i={name:"classics/zixia/056.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_54、【歸妹】-兌下震上" tabindex="-1">54、【歸妹】 兌下震上 <a class="header-anchor" href="#_54、【歸妹】-兌下震上" aria-label="Permalink to “54、【歸妹】 兌下震上”">​</a></h1><p>卦辭：歸妹，徵兇，無攸利。</p><p>彖曰：歸妹，天地之大義也。天地不交，而萬物不興。歸妹，人之終始也。説以動，所歸妹也。徵兇，位不當也。無攸利，柔乘剛也。</p><p>子夏：少女之窮也，無所往而歸其長陽。女説其有歸，而往也。男説其有家，而娶也。有生化之義焉，不交則無終也。故少配長説，以與動有終，而自此始也。少陰失位以求合，人斯賊之矣。不足以相久，徵其兇哉。柔得中，眾之歸也。隂雖從陽，陽下其隂，失其位也。柔制其剛也。豈人倫之序哉，不足以獨化也。故無攸利至於終，存乎生化之大義焉。</p><p>象曰：澤上有雷，歸妹。君子以永終知敝。</p><p>子夏：澤之濡雷，震於其上，雨微而雷震。雖不當於大，亦相歸之物也。無歸也，斯敝之矣。君子知其敝，無所往，故歸而永終也。</p><p>初九，歸妹以娣，跛能履，徵吉。</p><p>象曰：歸妹以娣，以恆也。跛能履，吉相承也。</p><p>子夏：無所往歸之矣。初説而後動也，何不可乎。故?娣雖不足行，茍能徵，則吉。周禮曰：歸，以恆者也。柔而隨剛，吉相承也。歸妹相終，非情故以。禮歸之。</p><p>九二，眇能視，利幽人之貞。</p><p>象曰：利幽人之貞，未變常也。</p><p>子夏：剛居內而應，柔之制也。道之反，不足以為明也。眇而視者矣。自守其幽，不變其常，雖利也。豈娶之道哉。</p><p>六三，歸妹以須，反歸以娣。</p><p>象曰：歸妹以須，未當也。</p><p>子夏：夫以不敵將配以仁者，遽而行之不能終也。故待其所從道極，相説而來，歸以娣可也。未當故也。</p><p>九四，歸妹愆期，遲歸有時。</p><p>象曰：愆期之志，有待而行也。</p><p>子夏：過下升上，陽以居隂，剛過其柔也。得其無與，合而來之，義也。遲歸有時，此得待而行也。</p><p>六五，帝乙歸妹，其君之袂，不如其娣之袂。良月幾望，吉。</p><p>象曰：帝乙歸妹，不如其娣之袂良也。其位在中以貴行也。</p><p>子夏：殷王之少，妹歸妹之貴也。古者王女下嫁於諸侯，衣服不繫其夫。下王后一等，故君之袂，不如娣之袂。妻貴於夫，夫下妻也。故見其妻象焉。月幾望，隂盈盛也。隂而得中，無與爭者，故吉也。</p><p>上六，女承筐，無實士。刲羊無血，無攸利。</p><p>象曰：上六，無實承虛筐也。</p><p>子夏：柔而居極，歸妹之窮也。復何待乎。無其歸者也。女徒承筐，不見其實也。士求進，安得其偶哉。道之窮而無所利也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
